package net.imadz.codegen.scaffolding.cqrs

import java.nio.charset.StandardCharsets
import java.nio.file.{Files, Path}

/** S2-41 R7：标记块部分文件合并写盘——writeArtifact 整文件模式的扩展（node gen_api_controllers/
  * index.mjs:93-108 先例的 Scala 化；EP_Controller_ReadSide_Routes 合并策略三路径）：
  * ①目标不存在 → 新建（头注释＋标记块——块外零内容）；
  * ②存在且含标记对 → 只替换两标记间的段（标记行文案恒定→幂等复跑字节稳定）；段外逐字节保留；
  * ③存在无标记 → 文件尾追加（一行提示注释＋空行分隔·零删除零改写）。
  * 标记态畸形（有起无止／有止无起）fail-fast：静默追加会产生双起始标记，下一轮段替换会吞掉
  * 手写领地（H052/H053 生成期 fail-fast 先例——炸出优于静默错删）。
  * 指纹豁免：本写入器不注入 `@generated by` 整文件指纹——标记块文件是共享领地，整文件指纹会
  * 翻转 gen_manifest 的 KEEP/COVER 判定为 COVER 冲掉段外手写行（调用方头注释同受此约束）。 */
object MarkerBlockWriter {

  /** @param block 完整标记块（首行＝markerStart·末行＝markerEnd——RoutesTemplate.generate 产物）。
    * @param newFileHeader 目标不存在时的文件头注释行（指向生成器·不含 `@generated by` 指纹）。
    * @param appendNotice 无标记追加路径的一行提示注释。 */
  def write(
      target: Path,
      markerStart: String,
      markerEnd: String,
      block: String,
      newFileHeader: Seq[String],
      appendNotice: String
  ): Unit = {
    val existing =
      if (Files.exists(target))
        Some(new String(Files.readAllBytes(target), StandardCharsets.UTF_8))
      else None
    existing match {
      case None =>
        // ①新建：头注释＋空行＋标记块（块外零内容）
        Files.createDirectories(target.getParent)
        val content = (newFileHeader :+ block).mkString("\n") + "\n"
        Files.write(target, content.getBytes(StandardCharsets.UTF_8))
        println(s"🛣  Wrote marker-block file: $target")
      case Some(text) =>
        val startIdx = text.indexOf(markerStart)
        val endAfterStart =
          if (startIdx < 0) -1 else text.indexOf(markerEnd, startIdx + markerStart.length)
        if (startIdx >= 0 && endAfterStart >= 0) {
          // ②含标记对：段替换（node index.mjs:102 regex 语义——起标记起→其后首个止标记止·
          // 含标记行整体；标记行文案恒定→幂等复跑字节稳定，段外逐字节保留）
          val pattern = java.util.regex.Pattern.compile(
            java.util.regex.Pattern.quote(markerStart) +
              "[\\s\\S]*?" +
              java.util.regex.Pattern.quote(markerEnd)
          )
          val merged = pattern
            .matcher(text)
            .replaceFirst(java.util.regex.Matcher.quoteReplacement(block))
          Files.write(target, merged.getBytes(StandardCharsets.UTF_8))
          println(s"🛣  Merged marker-block segment: $target")
        } else if (startIdx < 0 && text.indexOf(markerEnd) < 0) {
          // ③无标记：尾追加（提示注释＋空行分隔——node index.mjs:104 trimEnd+block 同构；
          // 零删除零改写：既有内容仅规整尾随空白）
          val merged = text.replaceAll("\\s+$", "") + "\n\n" +
            appendNotice + "\n" + block + "\n"
          Files.write(target, merged.getBytes(StandardCharsets.UTF_8))
          println(s"🛣  Appended marker-block segment: $target")
        } else {
          throw new IllegalStateException(
            s"[MarkerBlockWriter] $target 标记态畸形（markerStart@$startIdx markerEnd@${text.indexOf(markerEnd)}）——" +
              s"半标记状态不可静默合并（追加会产生双起始标记，下轮段替换将吞掉手写领地）；请手工修复标记对后重跑"
          )
        }
    }
  }
}
